import { Step } from './types';

export class LoopController {
  private retryCount: number = 0;

  async executeStep(step: Step): Promise<void> {
    while (this.retryCount < 5) {
      try {
        await step.execute();
        this.retryCount = 0; // Reset retry count on success
        break;
      } catch (error) {
        this.retryCount++;
        console.warn(`Retrying step due to error: ${error.message}, Retry count: ${this.retryCount}`);
      }
    }
    if (this.retryCount === 5) {
      throw new Error(`Exceeded max retry count of 5 for step: ${step.name}`);
    }
  }
}

